-- MindWell schema (generated by `flask export-schema` from backend/app/models.py).
-- Preferred setup is `flask init-db`; this file is for review or manual setup.
CREATE DATABASE IF NOT EXISTS mindwell CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mindwell;

CREATE TABLE badges (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	code VARCHAR(40) NOT NULL, 
	name VARCHAR(60) NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	icon VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	email VARCHAR(254) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	`role` VARCHAR(16) NOT NULL, 
	display_name VARCHAR(80) NOT NULL, 
	is_active BOOL NOT NULL, 
	is_demo BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_login_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_users_role CHECK (role IN ('student','teacher')), 
	UNIQUE (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_users_is_demo ON users (is_demo);
CREATE INDEX ix_users_role ON users (`role`);

CREATE TABLE activities (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	slug VARCHAR(64), 
	title VARCHAR(100) NOT NULL, 
	description VARCHAR(400) NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	instructions JSON NOT NULL, 
	config JSON, 
	duration_minutes SMALLINT NOT NULL, 
	difficulty VARCHAR(10) NOT NULL, 
	completion_criteria VARCHAR(300) NOT NULL, 
	xp_reward SMALLINT NOT NULL, 
	safety_notes VARCHAR(300), 
	source VARCHAR(10) NOT NULL, 
	owner_student_id INTEGER, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_activities_kind CHECK (kind IN ('breathing','journal','guided_steps')), 
	CONSTRAINT ck_activities_category CHECK (category IN ('breathing','mindfulness','journaling','gratitude','movement','study_break','relaxation','sleep','time_management')), 
	CONSTRAINT ck_activities_difficulty CHECK (difficulty IN ('easy','moderate')), 
	CONSTRAINT ck_activities_duration CHECK (duration_minutes BETWEEN 1 AND 30), 
	UNIQUE (slug), 
	FOREIGN KEY(owner_student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_activities_category ON activities (category);
CREATE INDEX ix_activities_owner_student_id ON activities (owner_student_id);

CREATE TABLE checkins (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	checkin_date DATE NOT NULL, 
	stress SMALLINT, 
	anxiety SMALLINT, 
	mood SMALLINT, 
	sleep_hours FLOAT, 
	sleep_quality SMALLINT, 
	academic_pressure SMALLINT, 
	stressors JSON, 
	note VARCHAR(1000), 
	stress_level FLOAT, 
	anxiety_level FLOAT, 
	mood_level FLOAT, 
	sleep_score FLOAT, 
	academic_pressure_level FLOAT, 
	wellness_index FLOAT, 
	items_answered SMALLINT NOT NULL, 
	scoring_version VARCHAR(10) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_checkin_student_day UNIQUE (student_id, checkin_date), 
	CONSTRAINT ck_checkins_stress CHECK (stress IS NULL OR (stress BETWEEN 1 AND 5)), 
	CONSTRAINT ck_checkins_anxiety CHECK (anxiety IS NULL OR (anxiety BETWEEN 1 AND 5)), 
	CONSTRAINT ck_checkins_mood CHECK (mood IS NULL OR (mood BETWEEN 1 AND 5)), 
	CONSTRAINT ck_checkins_sleep_quality CHECK (sleep_quality IS NULL OR (sleep_quality BETWEEN 1 AND 5)), 
	CONSTRAINT ck_checkins_sleep_hours CHECK (sleep_hours IS NULL OR (sleep_hours BETWEEN 0 AND 16)), 
	CONSTRAINT ck_checkins_academic CHECK (academic_pressure IS NULL OR (academic_pressure BETWEEN 1 AND 5)), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_checkin_student_date ON checkins (student_id, checkin_date);

CREATE TABLE classrooms (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(120) NOT NULL, 
	teacher_id INTEGER NOT NULL, 
	join_code VARCHAR(12) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(teacher_id) REFERENCES users (id) ON DELETE CASCADE, 
	UNIQUE (join_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_classrooms_teacher_id ON classrooms (teacher_id);

CREATE TABLE consent_records (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	consent_type VARCHAR(40) NOT NULL, 
	granted BOOL NOT NULL, 
	version VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_consent_records_student_id ON consent_records (student_id);

CREATE TABLE conversations (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	summarized_through_message_id INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_conv_student_updated ON conversations (student_id, updated_at);

CREATE TABLE emergency_alerts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	client_request_id VARCHAR(64) NOT NULL, 
	channel VARCHAR(10) NOT NULL, 
	destination_masked VARCHAR(60) NOT NULL, 
	`trigger` VARCHAR(20) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_emergency_alerts_status CHECK (status IN ('not_configured','dev_outbox','accepted_by_provider','failed')), 
	CONSTRAINT uq_alert_request UNIQUE (student_id, client_request_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_alert_student_created ON emergency_alerts (student_id, created_at);

CREATE TABLE emergency_contacts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	relationship VARCHAR(40) NOT NULL, 
	phone_e164 VARCHAR(20) NOT NULL, 
	email VARCHAR(254), 
	preferred_method VARCHAR(10) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_emergency_contacts_preferred_method CHECK (preferred_method IN ('call_only','email','sms')), 
	UNIQUE (student_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE emergency_sharing_preferences (
	student_id INTEGER NOT NULL, 
	alerts_enabled BOOL NOT NULL, 
	share_name BOOL NOT NULL, 
	share_callback_phone BOOL NOT NULL, 
	callback_phone_e164 VARCHAR(20), 
	share_custom_note BOOL NOT NULL, 
	custom_note VARCHAR(200), 
	consent_version VARCHAR(20), 
	consented_at DATETIME, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (student_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE student_badges (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	badge_id INTEGER NOT NULL, 
	earned_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_student_badge UNIQUE (student_id, badge_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(badge_id) REFERENCES badges (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_student_badges_student_id ON student_badges (student_id);

CREATE TABLE student_profiles (
	user_id INTEGER NOT NULL, 
	pronouns VARCHAR(40), 
	year_of_study VARCHAR(40), 
	ai_processing_consent BOOL NOT NULL, 
	memory_enabled BOOL NOT NULL, 
	personalize_with_checkins BOOL NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE student_progress (
	student_id INTEGER NOT NULL, 
	total_xp INTEGER NOT NULL, 
	current_streak INTEGER NOT NULL, 
	longest_streak INTEGER NOT NULL, 
	last_active_date DATE, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (student_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE teacher_profiles (
	user_id INTEGER NOT NULL, 
	department VARCHAR(120), 
	PRIMARY KEY (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE xp_transactions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	amount INTEGER NOT NULL, 
	reason VARCHAR(120) NOT NULL, 
	source_type VARCHAR(20) NOT NULL, 
	source_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_xp_source UNIQUE (source_type, source_id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_xp_student_created ON xp_transactions (student_id, created_at);

CREATE TABLE activity_recommendations (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	activity_id INTEGER NOT NULL, 
	for_date DATE NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	reason VARCHAR(200) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_activity_recommendations_status CHECK (status IN ('suggested','dismissed','completed')), 
	CONSTRAINT uq_rec_student_activity_day UNIQUE (student_id, activity_id, for_date), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(activity_id) REFERENCES activities (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_rec_student_date ON activity_recommendations (student_id, for_date);

CREATE TABLE activity_sessions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	activity_id INTEGER NOT NULL, 
	started_at DATETIME NOT NULL, 
	completed_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(activity_id) REFERENCES activities (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_activity_sessions_student_id ON activity_sessions (student_id);

CREATE TABLE class_insights (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	class_id INTEGER NOT NULL, 
	period_weeks SMALLINT NOT NULL, 
	statistics JSON NOT NULL, 
	observations JSON NOT NULL, 
	ai_narrative JSON, 
	ai_status VARCHAR(30) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(class_id) REFERENCES classrooms (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_class_insights_class_id ON class_insights (class_id);

CREATE TABLE class_memberships (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	class_id INTEGER NOT NULL, 
	student_id INTEGER NOT NULL, 
	share_aggregates BOOL NOT NULL, 
	joined_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_class_student UNIQUE (class_id, student_id), 
	FOREIGN KEY(class_id) REFERENCES classrooms (id) ON DELETE CASCADE, 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_class_memberships_class_id ON class_memberships (class_id);
CREATE INDEX ix_class_memberships_student_id ON class_memberships (student_id);

CREATE TABLE memory_items (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	content VARCHAR(1000) NOT NULL, 
	source_conversation_id INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_memory_items_kind CHECK (kind IN ('student_note','ai_summary')), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_conversation_id) REFERENCES conversations (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_memory_student_created ON memory_items (student_id, created_at);

CREATE TABLE messages (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	conversation_id INTEGER NOT NULL, 
	`role` VARCHAR(16) NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	content TEXT NOT NULL, 
	safety_level VARCHAR(10) NOT NULL, 
	suggested_activity_ids JSON, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_messages_role CHECK (role IN ('user','assistant')), 
	CONSTRAINT ck_messages_source CHECK (source IN ('student','gemini','safety_template')), 
	CONSTRAINT ck_messages_safety_level CHECK (safety_level IN ('none','concern','crisis')), 
	FOREIGN KEY(conversation_id) REFERENCES conversations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_messages_conversation_id ON messages (conversation_id);

CREATE TABLE notification_attempts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	alert_id INTEGER NOT NULL, 
	attempt_no SMALLINT NOT NULL, 
	provider VARCHAR(20) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	provider_reference VARCHAR(100), 
	error_code VARCHAR(60), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(alert_id) REFERENCES emergency_alerts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_notification_attempts_alert_id ON notification_attempts (alert_id);

CREATE TABLE activity_completions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	session_id INTEGER NOT NULL, 
	student_id INTEGER NOT NULL, 
	activity_id INTEGER NOT NULL, 
	completion_date DATE NOT NULL, 
	elapsed_seconds INTEGER NOT NULL, 
	xp_awarded INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (session_id), 
	FOREIGN KEY(session_id) REFERENCES activity_sessions (id) ON DELETE CASCADE, 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(activity_id) REFERENCES activities (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_activity_completions_activity_id ON activity_completions (activity_id);
CREATE INDEX ix_completion_student_date ON activity_completions (student_id, completion_date);

CREATE TABLE journal_entries (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	completion_id INTEGER, 
	prompt VARCHAR(300), 
	content TEXT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(completion_id) REFERENCES activity_completions (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_journal_entries_student_id ON journal_entries (student_id);
